<?php
$pdo=db();$scores=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') period,ROUND(AVG(score_percent),1) score,COUNT(*) attempts FROM attempts GROUP BY period ORDER BY period DESC LIMIT 12")->fetchAll();
$subjects=$pdo->query("SELECT s.name,ROUND(AVG(CASE WHEN r.is_correct=1 THEN 100 ELSE 0 END),1) accuracy,COUNT(r.id) responses FROM subjects s LEFT JOIN questions q ON q.subject_id=s.id LEFT JOIN responses r ON r.question_id=q.id GROUP BY s.id ORDER BY accuracy DESC")->fetchAll();
$study=(float)$pdo->query('SELECT COALESCE(SUM(duration_minutes),0)/60 FROM study_logs')->fetchColumn();
?><div class="page-heading"><div><p class="eyebrow">UNDERSTAND YOUR PROGRESS</p><h1>Learning Analytics</h1><p class="muted">Use evidence from your learning activity to decide what to do next.</p></div><a class="btn secondary" href="api/export.php">Export my data</a></div>
<div class="stat-grid"><div class="stat-card"><span class="stat-icon blue">◷</span><div><small>Total study hours</small><strong><?=number_format($study,1)?></strong></div></div><div class="stat-card"><span class="stat-icon green">✓</span><div><small>Assessment attempts</small><strong><?=array_sum(array_column($scores,'attempts'))?></strong></div></div></div>
<div class="dashboard-grid"><section class="card span-2"><h2>Monthly assessment trend</h2><?php if(!$scores):?><div class="empty-state compact">Complete assessments to build your performance trend.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Month</th><th>Average score</th><th>Attempts</th></tr></thead><tbody><?php foreach(array_reverse($scores) as $s):?><tr><td><?=e($s['period'])?></td><td><b><?=e((string)$s['score'])?>%</b></td><td><?=$s['attempts']?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="card"><h2>Subject performance</h2><?php if(!$subjects):?><p class="muted">Add subjects and attempt questions to see topic performance.</p><?php else:foreach($subjects as $s):?><div class="metric-row"><span><?=e($s['name'])?></span><b><?=number_format((float)$s['accuracy'],1)?>%</b></div><?php endforeach;endif;?></section></div>
